const read = function registrationAnswers({ response, nameField, emailField }) {
  const fields = response.definition?.fields, answers = response.answers;
  if (!Array.isArray(fields) || !Array.isArray(answers)) throw new Error('Typeform response must include field definitions and answers');
  const read = (selector, expectedType) => {
    if (typeof selector !== 'string' || !selector) throw new Error('Configure the name and email question identifiers');
    const matches = fields.filter((field) => field.id === selector || field.ref === selector || field.title === selector);
    if (matches.length !== 1 || typeof matches[0].id !== 'string') throw new Error('Typeform field must match one unique question: ' + selector);
    const values = answers.filter((answer) => answer.field?.id === matches[0].id);
    if (values.length !== 1 || values[0].type !== expectedType || typeof values[0][expectedType] !== 'string') throw new Error('Typeform answer is missing or has the wrong type: ' + selector);
    return values[0][expectedType];
  };
  const name = read(nameField, 'text'), email = read(emailField, 'email');
  if (name.length < 3 || !name.trim()) throw new Error('Demio requires a first name of at least three characters');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Typeform email answer is invalid');
  return { name, email };
}

return {json:read({response:$json.form_response,nameField:"Let's start with your name.",emailField:"What's your email address?"})};
